    buy( shard_of(family_jungle(), stat_health()), jungle_n )
    buy( shard(stat_strength()), strength_shards )
    buy( shard(stat_health()), rest_after_jungle - strength_shards )
    if health() < max_health() and not exists(first(filter(foes, in_attack_range()))):
        end_turn()

# retreat at 30% health; recall only when no enemy is close
if not at_spawn and health() < 0.3 * max_health():
    if (in_danger() or enemies_within(8) > 0):
        let home = closest( spawn_region(ally()) )
        if fuel_remaining() > 60000:
            dash_to(0, home)
            dash_to(1, home)
        move_towards(home)
        end_turn()
    recall()
    end_turn()
if not at_spawn and gems() > 0 and health() < 0.5 * max_health() and not (in_danger() or enemies_within(8) > 0):
    recall()
    end_turn()

# CAST-AHEAD: damage/stun a close enemy champion before it reaches us
if exists( first(foes) ):
    let near_foe = nearest( foes )
    if exists(near_foe) and distance(position(), unit_position(near_foe)) <= 4 and not contains( spawn_region(enemy()), unit_position(near_foe) ):
        set_team_target(near_foe)
        if ability_ready(0) and not slot_is_dash(0) and not slot_is_shield(0) and not slot_is_heal(0):
            cast_at_unit(0, near_foe)
        if ability_ready(1) and not slot_is_dash(1) and not slot_is_shield(1) and not slot_is_heal(1):
            cast_at_unit(1, near_foe)

let enemy = weakest( filter( foes, in_attack_range() ) )
if exists(enemy) and not contains( spawn_region(enemy()), unit_position(enemy) ):
    cast_on(0, enemy)
    cast_on(1, enemy)
    attack(enemy)
    if ability_ready(0) and slot_is_reset(0):
        cast_self(0)
    if ability_ready(1) and slot_is_reset(1):
        cast_self(1)
    attack(enemy)
    end_turn()

# place the team's altar lock when holding it with an empty bag next to an altar
if gems() == 0 and has_altar_lock() and fuel_remaining() > 60000:
    let lp_v = read_shared(7)
    if lp_v - 2 * floor( lp_v / 2 ) == 0:
        let lock_altar = first( filter( altars(), within(2, position()) ) )
        if exists(lock_altar):
            place_altar_lock(lock_altar)
            write_shared(7, lp_v + 1)
            end_turn()

# CONVERSION: bank at a bag of 15, 6+ when an altar is within 2 turns, 10+ when an altar is within 4,
# 6+ when an enemy is about to reach us; always when hurt or late
let bag_ready = gems() >= 15 or (gems() >= 6 and altar_eta() <= 1) or (gems() >= 10 and altar_eta() <= 4) or (gems() >= 6 and threat_eta() <= 3) or round_number() > 1500 or health() < 0.3 * max_health()
if gems() > 0 and bag_ready:
    let altar = first( filter( altars(), within(1, position()) ) )
    if exists(altar):
        tribute(altar)
        end_turn()
    let target = closest( minus( safe_altar_ring, ring(locked_altars(), 1) ) )
    if exists(target):
        move_towards(target)
        end_turn()
    let target2 = closest(safe_altar_ring)
    if exists(target2):
        move_towards(target2)
        end_turn()
    let altar_goal = closest(altar_ring)
    if contains(camp_spawns, altar_goal):
        let blocker = first( filter( camps_visible(), in_attack_range() ) )
        if exists(blocker):
            attack(blocker)
            end_turn()
    move_towards( altar_goal )
    end_turn()

let camps = camps_visible()

let camp = first( filter( camps, in_attack_range() ) )
if exists(camp):
    cast_on(0, camp)
    cast_on(1, camp)
    attack(camp)
    if ability_ready(0) and slot_is_reset(0):
        cast_self(0)
    if ability_ready(1) and slot_is_reset(1):
        cast_self(1)
    attack(camp)
    end_turn()

if team_score(ally()) == 0 and round_number() > 800:
    move_towards( closest( minus( minus( camp_spawns, respawning_visible_spawns() ), golem_tiles() ) ) )
    end_turn()
let goals = minus( minus( minus( minus( camp_spawns, respawning_visible_spawns() ), monolith_tiles() ), golem_tiles() ), mono_groups )

if contains(capturable_spawns(), position()):
    end_turn()

let goal = closest(goals)
# bank before a dangerous group (elk 60, wolf 20 per camp): from a bag of 6 instead of 10
if exists(goal) and gems() >= 6 and group_threat(goal) >= 240 and fuel_remaining() > 65000:
    let bank_altar = first( filter( altars(), within(1, position()) ) )
    if exists(bank_altar):
        tribute(bank_altar)
        end_turn()
    move_towards( closest(safe_altar_ring) )
    end_turn()
# altar on the way to the goal: tribute as we pass it. Free when no detour; a big bag also takes a short detour
if exists(goal) and gems() > 0 and fuel_remaining() > 115710 and (bank_detour(goal) == 0 or (gems() >= BIG_BAG and bank_detour(goal) <= BANK_DETOUR_MAX)):
    let way_altar = first( filter( altars(), within(1, position()) ) )
    if exists(way_altar):
        tribute(way_altar)
        end_turn()
# on a dead camp of an uncleared group, walk to the nearest living camp instead
if distance(goal, position()) == 0:
    let live = nearest(camps)
    if exists(live) and not contains( union( monolith_tiles(), golem_tiles() ), unit_position(live) ):
        move_towards( unit_position(live) )
        end_turn()
if exists(goal) and distance(position(), goal) > 2 and fuel_remaining() > 55000:
    dash_to(0, goal)
    dash_to(1, goal)
# VISION: no enemy in sight while standing in a bush, ward our own tile
if count(foes) == 0 and contains( bushes(), position() ):
    place_ward( position() )
move_towards( goal )
let camp2 = first( filter( camps, in_attack_range() ) )
if exists(camp2):
    attack(camp2)
set_priority( 1 + random_int(100) )
end_turn()

# tune-v20-L1c [tune line] + conversion v6: v1 plus a rich-group pull. When a camp group worth >= 15 gems
# is at most 4 tiles farther than the nearest camp, walk to the rich one first (bags of 15+ per capture).
# One buy per team (bit 1 of shared byte 7 = bought), one placement (bit 0 = placed).

def cast_on(slot, u):
    if ability_ready(slot):
        if slot_is_shield(slot) or slot_is_heal(slot):
            cast_self(slot)
        elif not slot_is_dash(slot):
            cast_at_unit(slot, u)

def dash_to(slot, t):
    if ability_ready(slot):
        if slot_is_dash(slot):
            dash_towards(slot, t)

# ---- draft ----
if is_draft():
    let pool = unpicked_champions()
    if available(pool, champ_vendetta()):
        pick(champ_vendetta())
    elif available(pool, champ_vesper_vale()):
        pick(champ_vesper_vale())
    elif available(pool, champ_tavi()):
        pick(champ_tavi())
    elif available(pool, champ_ryth()):
        pick(champ_ryth())
    elif available(pool, champ_ren()):
        pick(champ_ren())
    else:
        pick( random_champion(pool) )
    end_turn()

# ---- every turn ----
keep camp_spawns = camp_spawn_tiles()
# monolith groups never change: one group_tiles() per game (fuel; bot-session check)
keep mono_groups = group_tiles( monolith_tiles() )
keep altar_ring = ring( altars(), 1 )
keep safe_altar_ring = ring( minus( altars(), ring(monolith_tiles(), 5) ), 1 )
# camp groups worth 15+ gems when cleared (static)
keep rich = rich_spawns(15)

if not alive() or channeling() or (not can_move() and not can_attack()):
    end_turn()

let at_spawn = contains( spawn_region(ally()), position() )
# one enemies_visible() query per turn, reused below (no move happens before its last use)
let foes = enemies_visible()
if at_spawn:
    # lock once: one altar lock per team per game. Shared byte 7: bit 0 = placed, bit 1 = bought (bits 2-7 free).
    let lk_v = read_shared(7)
    let lk_placed = lk_v - 2 * floor( lk_v / 2 )
    let lk_bought = floor( lk_v / 2 ) - 2 * floor( lk_v / 4 )
    if lk_placed == 0 and lk_bought == 0 and not has_altar_lock():
        buy_altar_lock()
        if has_altar_lock():
            write_shared(7, lk_v + 2)
    let shards_bought = floor( gold() / 30 )
    let treasure_n = floor( shards_bought / 2 )
    let rest_after_treasure = shards_bought - treasure_n
    let jungle_n = floor( rest_after_treasure / 2 )
    let rest_after_jungle = rest_after_treasure - jungle_n
    let strength_shards = floor( rest_after_jungle / 2 )
    buy( shard_of(family_treasure(), stat_strength()), treasure_n )
    buy( shard_of(family_jungle(), stat_health()), jungle_n )
    buy( shard(stat_strength()), strength_shards )
    buy( shard(stat_health()), rest_after_jungle - strength_shards )
    # heal on spawn before heading back out, unless an enemy is already in reach
    if health() < max_health() and not exists(first(filter(foes, in_attack_range()))):
        end_turn()

# retreat at 30% health when in danger; recall only when clear (never start a recall with an enemy within 8)
if not at_spawn and health() < 0.3 * max_health():
    if (in_danger() or enemies_within(8) > 0):
        let home = closest( spawn_region(ally()) )
        # fuel gate: a long retreat's dash search can push the turn past 100k
        if fuel_remaining() > 60000:
            dash_to(0, home)
            dash_to(1, home)
        move_towards(home)
        end_turn()
    recall()
    end_turn()
if not at_spawn and gems() > 0 and health() < 0.5 * max_health() and not (in_danger() or enemies_within(8) > 0):
    recall()
    end_turn()

# CAST-AHEAD: cast damage/stun at a close enemy champion before it reaches us
if exists( first(foes) ):
    let near_foe = nearest( foes )
    if exists(near_foe) and distance(position(), unit_position(near_foe)) <= 4 and not contains( spawn_region(enemy()), unit_position(near_foe) ):
        set_team_target(near_foe)
        if ability_ready(0) and not slot_is_dash(0) and not slot_is_shield(0) and not slot_is_heal(0):
            cast_at_unit(0, near_foe)
        if ability_ready(1) and not slot_is_dash(1) and not slot_is_shield(1) and not slot_is_heal(1):
            cast_at_unit(1, near_foe)

let enemy = weakest( filter( foes, in_attack_range() ) )
# an enemy on its own spawn is healed every turn: fighting it there never ends (00reverse-spiral)
if exists(enemy) and not contains( spawn_region(enemy()), unit_position(enemy) ):
    cast_on(0, enemy)
    cast_on(1, enemy)
    attack(enemy)
    # attack reset: a second basic attack after the first (it does nothing before one)
    if ability_ready(0) and slot_is_reset(0):
        cast_self(0)
    if ability_ready(1) and slot_is_reset(1):
        cast_self(1)
    attack(enemy)
    end_turn()

# lock once: the champion holding the lock, bag empty, next to an altar: lock it against enemy tributes
if gems() == 0 and has_altar_lock() and fuel_remaining() > 60000:
    let lp_v = read_shared(7)
    if lp_v - 2 * floor( lp_v / 2 ) == 0:
        let lock_altar = first( filter( altars(), within(2, position()) ) )
        if exists(lock_altar):
            place_altar_lock(lock_altar)
            write_shared(7, lp_v + 1)
            end_turn()

# ALWAYS BANK NEXT TO AN ALTAR: any carried gems, one turn of channel for a small bag
let adj_altar = first( filter( altars(), within(0, position()) ) )
if gems() > 0 and exists(adj_altar):
    tribute(adj_altar)
    end_turn()

# CONVERSION: bank when the bag is worth it, when it is small but an altar is close, when an enemy
# can reach us while carrying, or when an enemy champion is within 7 tiles of a small bag
let bag_ready = gems() >= 25 or round_number() > 1500 or health() < 0.3 * max_health() or (gems() >= 8 and altar_eta() <= 8) or (gems() > 0 and threat_eta() <= 3) or (gems() >= 6 and enemies_near(position(), 7) > 0)
if gems() > 0 and bag_ready:
    # an altar next to us works even when locked: tributing there attacks the lock (5 hits clear it)
    let altar = first( filter( altars(), within(1, position()) ) )
    if exists(altar):
        tribute(altar)
        end_turn()
    # walk to an open altar out of monolith reach (5); else any altar out of reach; else any altar
    let target = closest( minus( safe_altar_ring, ring(locked_altars(), 1) ) )
    if exists(target):
        move_towards(target)
        end_turn()
    let target2 = closest(safe_altar_ring)
    if exists(target2):
        move_towards(target2)
        end_turn()
    let altar_goal = closest(altar_ring)
    # every altar-adjacent tile is taken by a camp: fight it
    if contains(camp_spawns, altar_goal):
        let blocker = first( filter( camps_visible(), in_attack_range() ) )
        if exists(blocker):
            attack(blocker)
            end_turn()
    move_towards( altar_goal )
    end_turn()

# one camps_visible() query per turn, reused for both attack checks
let camps = camps_visible()

let camp = first( filter( camps, in_attack_range() ) )
if exists(camp):
    cast_on(0, camp)
    cast_on(1, camp)
    attack(camp)
    if ability_ready(0) and slot_is_reset(0):
        cast_self(0)
    if ability_ready(1) and slot_is_reset(1):
        cast_self(1)
    attack(camp)
    end_turn()

# nothing tributed by round 800 (only monoliths carry gems): go for monoliths too
if team_score(ally()) == 0 and round_number() > 800:
    move_towards( closest( minus( minus( camp_spawns, respawning_visible_spawns() ), golem_tiles() ) ) )
    end_turn()
let goals = minus( minus( minus( minus( camp_spawns, respawning_visible_spawns() ), monolith_tiles() ), golem_tiles() ), mono_groups )

# already standing on a cleared camp spawn: hold here so the capture timer keeps running
if contains(capturable_spawns(), position()):
    end_turn()

let goal = closest(goals)
# the nearest rich camp group (15+ gems), intersected with the open goals: goals minus (goals minus rich)
let rich_goal = closest( minus( goals, minus( goals, rich ) ) )
# bank before a dangerous group: elk 60, wolf 20 per camp
if exists(goal) and gems() >= 10 and group_threat(goal) >= 240 and fuel_remaining() > 65000:
    let bank_altar = first( filter( altars(), within(1, position()) ) )
    if exists(bank_altar):
        tribute(bank_altar)
        end_turn()
    move_towards( closest(safe_altar_ring) )
    end_turn()
# the next camp lies on the way to an altar (small detour): bank on the way, then go on
if exists(goal) and gems() >= 10 and bank_detour(goal) <= 2 and fuel_remaining() > 65000:
    move_towards( closest(altar_ring) )
    end_turn()
# a rich group only a few tiles farther than the nearest camp: take it first (bigger bags per capture)
if exists(rich_goal) and distance(position(), rich_goal) > 0 and distance(position(), rich_goal) <= distance(position(), goal) + 4 and fuel_remaining() > 60000:
    move_towards( rich_goal )
    end_turn()
# on a dead camp of a group that is not cleared yet, walk to the nearest living camp instead
if distance(goal, position()) == 0:
    let live = nearest(camps)
    if exists(live) and not contains( union( monolith_tiles(), golem_tiles() ), unit_position(live) ):
        move_towards( unit_position(live) )
        end_turn()
# dash toward a camp goal only when it is farther than 2 tiles (fuel guarded)
if exists(goal) and distance(position(), goal) > 2 and fuel_remaining() > 55000:
    dash_to(0, goal)
    dash_to(1, goal)
# VISION: no enemy in sight on a camp walk, standing in a bush: ward our own tile
if count(foes) == 0 and contains( bushes(), position() ):
    place_ward( position() )
move_towards( goal )
let camp2 = first( filter( camps, in_attack_range() ) )
if exists(camp2):
    attack(camp2)
set_priority( 1 + random_int(100) )
end_turn()
